import java.util.Iterator;
	import java.lang.Long;
	import com.redwood.scheduler.api.model.*;
{
String query = "select fe.* from Job\n"
+"join JobWaitEvent jwe on jwe.Job = Job.UniqueId\n"
+"join Event ev on ev.UniqueId = jwe.RaisedEvent\n" 
+"join FileEvent fe on fe.Event = ev.UniqueId \n"
+"join EventDefinition ed on ed.UniqueId = ev.EventDefinition\n"
+"join FileEventDefinition fed on fed.EventDefinition = ed.UniqueId\n"
+"where Job.JobId = " + pProcessId;

Partition partition = jcsSession.getPartitionByName("%Partition%");
JobDefinition jobDefinition  = jcsSession.getJobDefinitionByName(partition,pDeliverScript); 

if (jobDefinition != null)
{    
	for (Iterator it = jcsSession.executeObjectQuery(query,null); it.hasNext(); )
	{
		FileEvent fileEvent = (FileEvent) it.next();
		String sourceFilepath = fileEvent.getOriginalPath();
		String destinationFolderpath = "/opt/mhi-ac/gateway/dev2/vendor_files/"+pSubfolder;
		jcsOut.println(sourceFilepath);
		jcsOut.println(destinationFolderpath);
		jcsOut.println(pDeliverScript);
		Job process = jobDefinition.prepare();
		process.getJobParameterByName("pSourceFilepath").setInValueString(sourceFilepath);
		process.getJobParameterByName("pDestinationFolderpath").setInValueString(destinationFolderpath);

		for (Iterator it2 = process.getJobParameters(); it2.hasNext(); )
		{
		  JobParameter param = (JobParameter) it2.next();
		  JobDefinitionParameter jobDefinitionParameter = (JobDefinitionParameter) param.getJobDefinitionParameter();
		  String parameterName = jobDefinitionParameter.getName();
		  if (jobDefinitionParameter.getDisplayOrder().longValue() == 2)
		  {
		    jcsOut.println(parameterName);
		    process.getJobParameterByName(parameterName).setInValueString(pDeliverScriptParameter);
		    jcsOut.println(pDeliverScriptParameter);
		  }
		}

		Queue queue = jcsSession.getQueueByName(partition, "%Partition%.%Queue%");
		process.setQueue(queue);

		jcsSession.persist();
	}
}
else
{
	jcsOut.println("Unknown delivery script");
}
}
